// Lights Out: 5×5 and 7×7 boards generated by random presses (always solvable), move counter, GF(2) solver for
// hints and par (minimum moves), best results per size kept in localStorage. Click/tap or arrow keys + Enter.
import { el, render, store, stat, toast } from '../../lib/ui.js';

/** Minimal-weight press set that turns all lights off, or null. lights: array of 0/1 length n*n. */
function solve(lights, n) {
  const V = n * n;
  // augmented rows: row[i] = bits of presses affecting cell i, plus rhs
  const rows = [];
  for (let i = 0; i < V; i++) {
    const row = new Uint8Array(V + 1); const r = Math.floor(i / n), c = i % n;
    for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) { const rr = r + dr, cc = c + dc; if (rr >= 0 && rr < n && cc >= 0 && cc < n) row[rr * n + cc] = 1; }
    row[V] = lights[i]; rows.push(row);
  }
  const pivotCol = [];
  let rank = 0;
  for (let col = 0; col < V && rank < V; col++) {
    let p = -1; for (let i = rank; i < V; i++) if (rows[i][col]) { p = i; break; }
    if (p < 0) continue;
    [rows[rank], rows[p]] = [rows[p], rows[rank]];
    for (let i = 0; i < V; i++) if (i !== rank && rows[i][col]) for (let k = col; k <= V; k++) rows[i][k] ^= rows[rank][k];
    pivotCol[rank] = col; rank++;
  }
  for (let i = rank; i < V; i++) if (rows[i][V]) return null; // inconsistent
  const isPivot = new Set(pivotCol);
  const free = []; for (let c = 0; c < V; c++) if (!isPivot.has(c)) free.push(c);
  const combos = Math.min(1 << Math.min(free.length, 12), 4096);
  let best = null;
  for (let m = 0; m < combos; m++) {
    const x = new Uint8Array(V);
    free.forEach((c, i) => { x[c] = (m >> i) & 1; });
    for (let i = rank - 1; i >= 0; i--) {
      let v = rows[i][V];
      for (const c of free) if (rows[i][c] && x[c]) v ^= 1;
      x[pivotCol[i]] = v;
    }
    let w = 0; for (let i = 0; i < V; i++) w += x[i];
    if (!best || w < best.w) best = { x, w };
  }
  return best ? Array.from(best.x) : null;
}

export default function (root) {
  const s = store('lights-out');
  let n = s.get('size', 5), lights = [], moves = 0, solved = false, solution = null, par = 0, hint = -1, cursor = 0, history = [];
  let best = s.get('best', {});

  const grid = el('div', { style: { display: 'grid', gap: '6px', width: 'min(100%, 420px)', margin: '0 auto', userSelect: 'none', touchAction: 'manipulation' } });
  const cells = [];
  const msg = el('div', { class: 'center', style: { fontWeight: '600', minHeight: '24px' } });
  const stats = el('div', { class: 'row', style: { justifyContent: 'center' } });
  const sizeSel = el('select', { class: 'select', value: String(n), onchange: () => { n = +sizeSel.value; s.set('size', n); newGame(); } },
    el('option', { value: '5' }, '5 × 5'), el('option', { value: '7' }, '7 × 7'));
  const hintBtn = el('button', { class: 'btn', onclick: showHint }, 'Hint');
  const undoBtn = el('button', { class: 'btn', onclick: undo }, 'Undo');

  function buildGrid() {
    grid.style.gridTemplateColumns = `repeat(${n}, 1fr)`;
    cells.length = 0; render(grid);
    for (let i = 0; i < n * n; i++) {
      const d = el('div', { style: { aspectRatio: '1', borderRadius: '8px', cursor: 'pointer', border: '2px solid transparent', transition: 'background .15s, box-shadow .15s' }, onclick: () => press(i, true) });
      cells.push(d); grid.append(d);
    }
  }
  function toggle(i) {
    const r = Math.floor(i / n), c = i % n;
    for (const [dr, dc] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) { const rr = r + dr, cc = c + dc; if (rr >= 0 && rr < n && cc >= 0 && cc < n) lights[rr * n + cc] ^= 1; }
  }
  function newGame() {
    buildGrid(); lights = Array(n * n).fill(0); moves = 0; solved = false; hint = -1; history = []; cursor = Math.floor(n * n / 2);
    const presses = n + Math.floor(Math.random() * (n * n - n));
    do { for (let k = 0; k < presses; k++) toggle(Math.floor(Math.random() * n * n)); } while (!lights.some(v => v));
    recompute();
    msg.textContent = `Switch all ${n * n} lights off. Par: ${par} moves.`;
    paint(); updateStats();
  }
  function recompute() { solution = solve(lights, n); if (moves === 0 && solution) par = solution.reduce((a, b) => a + b, 0); }
  function press(i, user) {
    if (solved) return;
    history.push(i); toggle(i); moves++; hint = -1; cursor = i;
    if (!lights.some(v => v)) {
      solved = true;
      const key = String(n); const b = best[key] || {};
      let note = '';
      if (!b.moves || moves < b.moves) { b.moves = moves; note = ' New best!'; }
      b.solved = (b.solved || 0) + 1; if (moves <= par) b.par = (b.par || 0) + 1; best[key] = b; s.set('best', best);
      msg.textContent = `Solved in ${moves} moves (par ${par}).${note} Press N or New board.`;
      updateStats();
    } else { recompute(); msg.textContent = `${moves} move${moves === 1 ? '' : 's'} — ${solution ? solution.reduce((a, b) => a + b, 0) + ' more needed at best' : ''}`; }
    paint();
  }
  function undo() {
    if (!history.length || solved) return;
    toggle(history.pop()); moves = Math.max(0, moves - 1); hint = -1; recompute(); paint();
    msg.textContent = `${moves} moves.`;
  }
  function showHint() {
    if (solved) return;
    if (!solution) { toast('No solution found'); return; }
    hint = solution.findIndex(v => v);
    if (hint < 0) toast('Already solved?'); else { msg.textContent = 'Press the highlighted light.'; cursor = hint; }
    paint();
  }
  function paint() {
    for (let i = 0; i < n * n; i++) {
      const d = cells[i];
      d.style.background = lights[i] ? 'var(--warn)' : 'var(--line)';
      d.style.boxShadow = lights[i] ? '0 0 14px var(--warn)' : 'none';
      d.style.borderColor = i === hint ? 'var(--danger)' : i === cursor && !solved ? 'var(--accent)' : 'transparent';
      d.style.opacity = solved ? '.6' : '1';
    }
  }
  function updateStats() {
    const b = best[String(n)] || {};
    render(stats, stat(moves, 'moves'), stat(par, 'par'), stat(b.moves || '–', `best (${n}×${n})`), stat(b.solved || 0, 'solved'), stat(b.par || 0, 'at par'));
  }
  function onKey(e) {
    if (e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)) return;
    const r = Math.floor(cursor / n), c = cursor % n;
    const d = { ArrowUp: [-1, 0], ArrowDown: [1, 0], ArrowLeft: [0, -1], ArrowRight: [0, 1] }[e.key];
    if (d) { e.preventDefault(); cursor = Math.max(0, Math.min(n - 1, r + d[0])) * n + Math.max(0, Math.min(n - 1, c + d[1])); paint(); }
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); if (solved) newGame(); else press(cursor); }
    else if (e.key === 'h' || e.key === 'H') showHint();
    else if (e.key === 'n' || e.key === 'N') newGame();
    else if (e.key === 'u' || e.key === 'U' || (e.key === 'z' && (e.ctrlKey || e.metaKey))) { e.preventDefault(); undo(); }
  }
  window.addEventListener('keydown', onKey);

  render(root,
    el('div', { class: 'row', style: { justifyContent: 'center' } }, sizeSel, el('button', { class: 'btn primary', onclick: newGame }, 'New board'), hintBtn, undoBtn),
    stats, msg, grid,
    el('div', { class: 'muted small center' }, 'Pressing a light toggles it and its four neighbours. Arrow keys move the cursor, Enter presses, H hints, U undoes, N starts a new board.'));
  newGame();
  return () => window.removeEventListener('keydown', onKey);
}
